<h1><?= htmlspecialchars( $account['display_name'], ENT_QUOTES, 'UTF-8' ) ?>’s team</h1><?php if ( ! empty( $saved ) ) : ?><p class="success"><?= 'submitted' === $entry['state'] ? 'Team amended.' : 'Draft saved.' ?> Version <?= (int) $entry['expected_version'] ?>.</p><?php endif; ?><?php if ( ! empty( $submitted ) ) : ?><p class="success">Your ten-pick team is submitted for season <?= (int) $entry['season'] ?>. It can be amended until the season deadline.</p><?php elseif ( 'submitted' === $entry['state'] ) : ?><p class="success">Your team is submitted for season <?= (int) $entry['season'] ?>. Changes create a new competing revision until the deadline.</p><?php endif; ?><?php if ( ! empty( $standing ) ) : ?><p class="standing">Current standing: rank <?= (int) $standing['rank'] ?> with <?= (int) $standing['points'] ?> points from <?= (int) $standing['scoring_picks'] ?> scoring picks.</p><?php endif; ?><p>Exactly ten picks. Your picks stay private until the season entry window closes. Existing picks remain if the catalogue later marks them unavailable.</p><form method="post" action="/team/save"><input type="hidden" name="_csrf" value="<?= htmlspecialchars( $csrf, ENT_QUOTES, 'UTF-8' ) ?>"><input type="hidden" name="season" value="<?= (int) $entry['season'] ?>"><input type="hidden" name="expected_version" value="<?= (int) $entry['expected_version'] ?>"><?php for ( $slot = 0; $slot < 10; ++$slot ) : $selected = $picks[ $slot ] ?? ''; ?><label for="pick<?= $slot ?>">Pick <?= $slot + 1 ?></label><select id="pick<?= $slot ?>" name="picks[]" required><option value="">Choose a person</option><?php foreach ( $people as $person ) : ?><option value="<?= htmlspecialchars( $person['uuid'], ENT_QUOTES, 'UTF-8' ) ?>"<?= $selected === $person['uuid'] ? ' selected' : '' ?>><?= htmlspecialchars( $person['name'], ENT_QUOTES, 'UTF-8' ) ?></option><?php endforeach; ?></select><?php endfor; ?><div class="row"><button>Save draft</button></div></form><?php if ( ! empty( $entry['draft_revision_id'] ) ) : ?><form method="post" action="/team/submit"><input type="hidden" name="_csrf" value="<?= htmlspecialchars( $csrf, ENT_QUOTES, 'UTF-8' ) ?>"><input type="hidden" name="season" value="<?= (int) $entry['season'] ?>"><input type="hidden" name="idempotency_key" value="<?= htmlspecialchars( bin2hex( random_bytes( 16 ) ), ENT_QUOTES, 'UTF-8' ) ?>"><button>Submit team</button></form><?php endif; ?>